#include <stdint.h>

#define RCC_BASE	0x40023800UL
#define RCC_AHB1ENR	(*((volatile uint32_t *)(RCC_BASE + 0x30)))
#define RCC_APB2ENR	(*((volatile uint32_t *)(RCC_BASE + 0x44)))

#define GPIOA_BASE	0x40020000UL
#define GPIOA_MODER	(*((volatile uint32_t *)(GPIOA_BASE + 0x00)))
#define GPIOA_IDR	(*((volatile uint32_t *)(GPIOA_BASE + 0x10)))

#define GPIOD_BASE	0x40020C00UL
#define GPIOD_MODER	(*((volatile uint32_t *)(GPIOD_BASE + 0x00)))
#define GPIOD_ODR	(*((volatile uint32_t *)(GPIOD_BASE + 0x14)))

#define SYSCFG_BASE	0x40013800UL
#define SYSCFG_EXTICR1	(*((volatile uint32_t *)(SYSCFG_BASE + 0x08)))

#define EXTI_BASE	0x40013C00UL
#define EXTI_IMR	(*((volatile uint32_t *)(EXTI_BASE + 0x00)))
#define EXTI_RTSR	(*((volatile uint32_t *)(EXTI_BASE + 0x08)))
#define EXTI_FTSR	(*((volatile uint32_t *)(EXTI_BASE + 0x0C)))
#define EXTI_PR		(*((volatile uint32_t *)(EXTI_BASE + 0x14))) // <- CLEAR SET 1

#define NVIC_ISER0    (*((volatile uint32_t *)(0xE000E100UL)))

// SysTick（Cortex-M4 internal）
#define SYSTICK_BASE  0xE000E010UL
#define SYSTICK_CTRL  (*((volatile uint32_t *)(SYSTICK_BASE + 0x00)))
#define SYSTICK_LOAD  (*((volatile uint32_t *)(SYSTICK_BASE + 0x04)))
#define SYSTICK_VAL   (*((volatile uint32_t *)(SYSTICK_BASE + 0x08)))

volatile uint32_t tick = 0;
volatile uint32_t last_tick = 0;

// SysTick 中斷 handler（每 1ms 觸發一次）
void SysTick_Handler(void)
{
    tick++;
}

void EXTI0_IRQHandler(void) {
	if ((tick - last_tick) <50 ) {
		EXTI_PR |= (1 << 0);
		return;
	}

	last_tick = tick;

	EXTI_PR |= (1 << 0);
	if (GPIOA_IDR & (1 << 0)) {

	}
	else {
		GPIOD_ODR ^= (1 << 12);
	}
}

int main(void)
{
	// 1. 設定 SysTick 每 1ms 中斷一次
	// 系統預設 clock = 16MHz
	// 16000000 / 1000 = 16000 counts per ms
	SYSTICK_LOAD = 16000 - 1;   // reload value
	SYSTICK_VAL  = 0;            // 清除目前值
	SYSTICK_CTRL = 0x7;          // bit0=enable, bit1=tickint, bit2=clksource(內部clock)

	RCC_AHB1ENR |= (1 << 0);
	RCC_AHB1ENR |= (1 << 3);
	RCC_APB2ENR |= (1 << 14);

	GPIOA_MODER &= ~(0x3 << (0*2));

	GPIOD_MODER &= ~(0x3 << (12*2));
	GPIOD_MODER |=  (0x1 << (12*2));

	SYSCFG_EXTICR1 &= ~(0xF << 0);

	EXTI_IMR |= (1 << 0);
	EXTI_RTSR |= (1 << 0);
	EXTI_FTSR |= (1 << 0);

	NVIC_ISER0 |= (1 << 6);

	while (1) {

	}

}

